   170→                ) != Vector128<byte>.Zero)
   171→            {
   172→                return GetInputLengthsMayOverflow(inputData);
   173→            }
   174→        }
   175→        else if (inputData.Slice(StartBaseLength, LengthSize - sizeof(uint)).IndexOfAnyExcept((byte)0) >= 0 ||
   176→                inputData.Slice(StartExpLength, LengthSize - sizeof(uint)).IndexOfAnyExcept((byte)0) >= 0 ||
